from dataclasses import dataclass
from math import ceil
from statistics import NormalDist


def fmt(value, digits=0):
    return f"{value:,.{digits}f}".replace(",", " ").replace(".", ",")


def rub(value, digits=0):
    return f"{fmt(value, digits)} ₽"


def pct(value, digits=1):
    return f"{fmt(value * 100, digits)}%"


@dataclass
class Model:
    headline: str
    columns: tuple
    rows: list
    arithmetic: str
    boundary: str
    stress: str
    scope: str
    evidence: str
    followup: str


def margin(values, detail):
    price, cost, fee, other, units, delta = values
    labels = ("Чистая цена", "Себестоимость", "Начисления услуг", "Прочие прямые расходы")
    names = {"price": 0, "cost": 1, "fee": 2, "other": 3}
    base = [price, cost, fee, other]
    axis = names[detail]
    after = base.copy()
    after[axis] += delta
    old = price - cost - fee - other
    new = after[0] - sum(after[1:])
    if min(base + after) <= 0 or min(old, new) <= 0:
        raise ValueError("Unit contribution scenario must stay positive")
    needed = ceil(units * old / new)
    minimum = sum(after[1:]) + old
    direction = f"на {rub(abs(delta))} {'больше' if delta > 0 else 'меньше'}"
    rows = [(label, rub(x), rub(y)) for label, x, y in zip(labels, base, after)]
    rows += [("Вклад с единицы", rub(old), rub(new)), ("Вклад за выбранный объём", rub(old * units), rub(new * units))]
    return Model(
        f"Что оставят {units} доставленных единиц",
        ("Показатель", "Обычный вариант", "Новый вариант"), rows,
        f"Берём {rub(price)} чистой цены, вычитаем {rub(cost)} себестоимости, {rub(fee)} услуг и {rub(other)} других прямых затрат. Получается {rub(old)} вклада за доставленную единицу. В сценарии одна строка меняется: «{labels[axis]}» становится {direction}, то есть {rub(after[axis])}. Повторяем расчёт и получаем {rub(new)}. На {units} доставленных единицах итог меняется с {rub(old * units)} до {rub(new * units)}. Поэтому в бюджете важно сохранить обе цифры: вклад на единицу позволяет сравнить модель, вклад всего объёма показывает сумму, с которой будет работать магазин.",
        f"Для сохранения результата {rub(old * units)} при новом вкладе нужно хотя бы {needed} доставленных единиц. Делим исходную сумму на новый вклад {rub(new)} и округляем вверх. При сохранении объёма и новых расходах альтернативный ориентир чистой цены составит {rub(minimum)}. Он получается сложением обновлённых прямых затрат с исходным вкладом {rub(old)}. Если часть услуг зависит от цены, пересчитайте саму сумму услуг при каждом ценовом варианте. Значение из расчёта с фиксированными расходами служит первым ориентиром для проверки.",
        f"Теперь проверим более слабый спрос. Возьмём {max(1, units * 4 // 5)} единиц вместо {units}. При том же новом вкладе магазин получит {rub(new * (units * 4 // 5))}. В варианте более высокого спроса берём {ceil(units * 1.2)} и получаем {rub(new * ceil(units * 1.2))}. В обоих вариантах это итог до расходов, которые не меняются с единицей, и до налога. Свой диапазон лучше построить по месяцам или неделям, где у товара были доступный остаток и близкие условия. Если в этот раз товар работает по другому графику, сравнивайте сопоставимые отрезки отдельно.",
        f"В исходные {rub(price)} и {rub(after[0])} включайте выручку продавца по одному и тому же правилу. Значение, которое видит покупатель на карточке, может включать разные механики скидок. В аналитике селлеров Яндекс Маркета полезно хранить рядом цену для покупателя и сумму, которую продавец признаёт своей выручкой. Когда магазин продаёт варианты в разных моделях или на разных складах, для начала выберите одну модель и один артикул. Так замена одной строки в расчёте имеет понятный смысл.",
        f"Сверьте {units} строк объёма с завершёнными продажами по выбранному товару. Если несколько единиц приехали в одном заказе, расходы на заказ нужно разнести по понятному правилу. В сравнении меняется именно вклад с одной доставленной единицы. Сохраните исходный файл и дату актуальности, поскольку часть расходов становится видна позже. Для позднего начисления обновите первоначальную строку с пометкой о дате, чтобы общей суммой не посчитать и ожидание, и факт.",
        f"После первого периода проставьте рядом новый фактический результат. Если получили {rub(new)} на единицу, но объём ожидали другой, не меняйте расчёт единицы задним числом. Сначала поясните разницу по количеству. Если же у {units} единиц состав расходов оказался другим, замените именно нужные позиции. Для небольшой команды рабочая версия помещается в файл с датой, артикулом, выбранным событием продажи и подтверждёнными суммами. К следующей закупке по этому файлу можно вернуться без ручного восстановления истории."
    )


def investment(values, item):
    setup, old, new, units = values
    saving = old - new
    needed = ceil(setup / saving)
    forecast = units * saving - setup
    lo = units * 3 // 4
    hi = ceil(units * 1.25)
    rows = [
        ("Расход на обработанную единицу", rub(old), rub(new)),
        ("Расход при ожидаемом объёме", rub(old * units), rub(new * units)),
        ("Разовый запуск", rub(0), rub(setup)),
        ("Всего за первый период", rub(old * units), rub(new * units + setup)),
    ]
    return Model(
        "Старый процесс и затраты на переход",
        ("Показатель", "Текущий процесс", "Новый процесс"), rows,
        f"Смотрим на рабочую единицу «{item}». Сейчас она требует {rub(old)}, после изменения ожидается {rub(new)}. Каждая обработанная единица даёт {rub(saving)} условной экономии. Для перехода нужно сразу потратить {rub(setup)}. При ожидаемом количестве {units} исходный способ за первый период стоит {rub(old * units)}, а новый {rub(new * units + setup)} с учётом разового запуска. Чистый эффект нового способа равен {rub(forecast)}. Разницу с точки зрения качества и времени исполнения оцениваем отдельными показателями.",
        f"Делим {rub(setup)} затрат на запуск на {rub(saving)} экономии. Получаем порог {needed} обработанных единиц при неизменных ставках. При {needed - 1} единицах разовый расход ещё не закрывается: эффект {rub((needed - 1) * saving - setup)}. При {needed} он составляет {rub(needed * saving - setup)}. Считать лучше с округлением до целой единицы, поскольку доля операции расходов не окупит. Если приходящая заявка обрабатывается несколько раз, для порога берите одно заранее выбранное определение события.",
        f"При снижении рабочей нагрузки до {lo} операций эффект составит {rub(lo * saving - setup)}. При увеличении до {hi} получится {rub(hi * saving - setup)}. Разница показывает, насколько результат зависит от загрузки, а не только от цены оборудования или настройки. Если на объёме {hi} потребуется другая смена или дополнительный платный расходник, добавьте его до сравнения. Если эффект при {lo} сильно хуже, согласуйте способ провести небольшой пилот и не переносить разовый бюджет на весь склад заранее.",
        f"Для аналитики селлера Яндекс Маркета важно решить, в каком месте процесса появляется единица «{item}». Считайте законченные операции и отмечайте повторные действия. Если сотруднику с почасовой оплатой стало легче, это может влиять на реальный денежный расход. Если на той же смене высвободилось время, занесите его отдельной строкой и укажите, на какие дополнительные операции это время можно направить. Экономию в рублях оценивайте по тем ставкам и условиям, которые меняются у магазина.",
        f"В книге расчёта сохраните как минимум два набора исходников: чем подтверждаются {rub(old)} и чем подтверждаются {rub(new)}. Для материалов берите цену на использованное количество, для работы фактическую оплату. Если в цене нового способа есть временная скидка, вынесите второй сценарий после её окончания. Себестоимость единицы лучше подтвердить на разных днях недели, иначе модель тренируется на одной спокойной смене. Период для первых {units} операций запишите заранее, чтобы не менять показатель после расчёта.",
        f"При подведении итогов посчитайте, сколько операций могли бы продолжить по старому процессу, и сколько реально прошло по новому. У порога {needed} сравнение особенно чувствительно к ошибкам в количестве и оплате. Если получили отклонение, найдите операцию, которая съела наибольшую долю времени, и пересчитайте только её норму. В отчёте держите результат в двух вариантах: с разовой покупкой {rub(setup)} и для следующего периода, где повторяются только расходы на работу."
    )


def quality(values, problem):
    volume, old, new, damage, work = values
    difference = old - new
    gross = difference * damage
    target = ceil(work / damage)
    rows = [("Проверено операций", volume, volume), ("Подтверждённые случаи", old, new),
        ("Доля случаев", pct(old / volume), pct(new / volume)),
        ("Прямой расход по случаям", rub(old * damage), rub(new * damage)),
        ("Разовый расход на изменение", "0 ₽", rub(work))]
    return Model(
        f"Проверка процесса на {volume} операциях",
        ("Показатель", "До изменения", "В пилоте"),rows,
        f"В условной группе из {volume} операций было {old} случаев, после изменения {new}. Показатель, который считаем в обеих группах, обозначим «{problem}». Его доля меняется с {pct(old / volume)} до {pct(new / volume)}. Если одно подтверждённое событие добавляет {rub(damage)} прямых расходов, условная разница равна {rub(gross)}. Вычитаем {rub(work)} пробного изменения и получаем эффект {rub(gross - work)}. Соотношение затрат полезнее оценивать именно для сопоставимых групп и на одинаковом сроке сбора доказательств.",
        f"Сколько подтверждённых случаев требуется предотвратить, чтобы покрыть {rub(work)}? Делим эту сумму на {rub(damage)} и округляем вверх до {target}. При {target - 1} предотвращённом случае эффект ещё не покрывает пробную трату. Уменьшение числа случаев с {old} до {new} даёт {difference} в примере. Если часть устранённых случаев стоила меньше среднего, возьмите подтверждённые затраты по каждому или выполните более строгий нижний расчёт. Обнаружить событие раньше и полностью избежать расхода часто оказываются двумя разными результатами.",
        f"При осторожной оценке {rub(damage * 0.8)} за случай эффект изменения равен {rub(difference * damage * 0.8 - work)}. При {rub(damage * 1.2)} за случай получится {rub(difference * damage * 1.2 - work)}. Оба значения считают {difference} подтверждённых предотвращённых событий. Если у вас мало наблюдений, одно дополнительное событие двигает долю на {pct(1 / volume, 2)} от всех операций. Для таких случаев сохраняйте количества и подбирайте срок оценки, в котором один заказ или одна поставка не определят весь вывод.",
        f"Для своего магазина определите базовую группу. Если из {volume} операций часть не требует этой проверки, разделите поток до расчёта. Отправка, товарная единица и потребительский заказ могут иметь разные размеры. Выберите одну единицу до измерения и оформите одинаковые фильтры на период. Обычно в рабочем отчёте хватает вида операции, даты, артикула и подтверждённой причины. Личные сведения покупателя в такой таблице не требуются. Аналитика Яндекс Маркета помогает связать операцию с данными кабинета, а причину на складе проверяют по своей записи.",
        f"Уточните, что вошло в условные {rub(damage)}. Можно записать прямую повторную упаковку, подтверждённый расход на повторную передачу или разницу при допустимой уценке. Временно остановившаяся работа, потерянный час и реальная выплата денег должны оставаться отдельно, пока команда не выберет правила для расчёта. Если один расход включён в другую сумму, отсеките повтор. В журнал полезно добавить графу с документом и ответственного, который может показать его по каждому заметному эпизоду.",
        f"После пилота сравните со снижением на {difference} случаев хотя бы ещё один сопоставимый период. Вопрос для смены звучит конкретно: сколько подтверждённых случаев дошли до следующего этапа и какие остановились внутренней проверкой. Если число уменьшилось, а часть заказов просто ещё не обработана, дождитесь одинакового возраста групп. Если доказано изменение процесса и затраты держатся на {rub(work)} или ниже, в итоговой таблице оставьте дату проверки факта и следующий срок пересмотра нормы."
    )


def cash(values, event):
    start, incoming, first, second, buffer = values
    interim = start - first
    current = interim + incoming - second
    delayed = interim - second
    minimum_transfer = max(0, buffer - delayed)
    partial = incoming // 2
    rows = [("Доступно на начало", rub(start), rub(start)), ("После обязательного платежа", rub(interim), rub(interim)),
        ("Перед вторым платежом", rub(interim + incoming), rub(interim)),
        ("Сразу после второго платежа", rub(current), rub(delayed)), ("Минимальный резерв", rub(buffer), rub(buffer))]
    return Model(
        "Деньги перед вторым платежом",
        ("Положение в календаре", "Поступление вовремя", "Поступление после платежа"),rows,
        f"На начало расчёта на счёте {rub(start)}. Первый обязательный расход {rub(first)}, после него доступно {rub(interim)}. Второй расход обозначим «{event}» и запланируем в размере {rub(second)}. Если ожидаемые {rub(incoming)} успеют поступить, сразу после второго расхода останется {rub(current)}. При переносе поступления после второго расхода в его момент будет {rub(delayed)}. Если эта цифра отрицательная, у магазина по условиям сценария средств на полный платёж не хватает. Сравнивать полезно на уровне конкретной даты и очередности операций.",
        f"Внутренний минимум магазина по сценарию {rub(buffer)}. Если поступление ещё не подтвердилось, максимум для второго расхода без нарушения минимума равен {rub(max(0, interim - buffer))}, при условии, что сам первый расход оставил нужный минимум. Чтобы сохранить резерв при полном платеже {rub(second)}, до него необходимо получить по меньшей мере {rub(minimum_transfer)} новых денег. Если уже после первого расхода остаток ниже минимума, вопрос стоит проверить до списания. Ожидаемое поступление может случиться в тот же день, но после списания оно полезно уже для следующей операции.",
        f"Проверим промежуточный случай. Из {rub(incoming)} перед оплатой пришла только половина, {rub(partial)}. После второго платежа остаток будет {rub(delayed + partial)}. Сравните его с минимумом {rub(buffer)}. Когда вы делите ожидаемую сумму на части, записывайте ближайшую подтверждённую часть отдельно от второй. Если в один день приходит несколько зачислений, важен порядок. Уточните его по выписке и договорённостям, а для самостоятельного плана оставьте вариант, где менее надёжная сумма приходит позже.",
        f"Кассовая аналитика селлеров Яндекс Маркета живёт по дате движения денег. Расчёт вклада использует свои периоды и помогает проверить экономику, однако оплачивать счета магазин будет из доступного остатка. В рабочей таблице полезно держать дату обязательства, дату ожидаемого списания, подтверждение поступления и остаток после действия. Для события «{event}» можно сохранить назначение платежа и контрагента во внутреннем журнале. В публичном разборе достаточно условных сумм без реквизитов.",
        f"Для {rub(start)} начального значения используйте доступный остаток на определённый момент, а не оборот за вчера. Отделите средства, которые нельзя расходовать или которые уже обещали по согласованному платежу. При сверке отдельно посмотрите выписку и данные расчётов площадки. Ближайший перевод из кабинета нужен как ожидаемая сумма, дата фактического поступления подтверждается банком. Если один из платежей включён в взаиморасчёт площадки, не добавляйте его вторым отдельным списанием без проверки.",
        f"План актуализируйте до запуска обязательства. После первого расхода {rub(first)} проверьте, совпал ли фактический остаток с {rub(interim)}. Если цифра ниже, найдите пропущенное списание, установите дату уточнения и пересчитайте оставшуюся неделю. После наступления оплаты отметьте факт и сравните минимальный дневной остаток с {rub(buffer)}. Такое сравнение показывает, помогает ли выбранный резерв обычным операциям, особенно когда плановое зачисление приходит позже."
    )


def stock(values, product):
    available, daily, lead, buffer, lot = values
    order_point = daily * lead + buffer
    gap = order_point - available
    before = available - daily * lead
    after = max(0, before) + lot
    rows=[("Доступный запас сегодня", available, available), ("Расход до поступления", daily * lead, daily * (lead + 2)),
        ("Точка заказа с резервом", order_point, daily * (lead + 2) + buffer),
        ("Остаток перед приходом по модели", before, available - daily * (lead + 2)),
        ("Доступно сразу после прихода, если продажи без ожидания", after, max(0,available-daily*(lead+2))+lot)]
    return Model(
        f"Запас на обычный срок и задержку в два дня",
        ("Показатель, в единицах", f"Через {lead} дней", f"Через {lead + 2} дней"), rows,
        f"Для примера «{product}» на сегодня доступно {available} единиц. Израсходуется около {daily} в день. До поступления и доступности следующей партии проходит {lead} календарных дней. Минимальная оценка расхода за ожидание: {daily} × {lead} = {daily * lead}. Прибавляем резерв {buffer} и получаем точку заказа {order_point}. Она показывает, какой доступный запас желательно иметь к началу ожидания. Положение относительно точки заказа: {available - order_point} единиц. Знак минус показывает, сколько товара не хватает для сохранения расчётного резерва.",
        f"Без дополнительной поставки и при прежнем темпе перед приходом модель даст остаток {before}. Если он ниже нуля, фактический склад не уйдёт в минус: число описывает возможный непокрытый спрос. После прихода {lot} единиц и при допущении, что неисполненный спрос не переносится, доступно {after}. Этого хватит примерно на {fmt(after / daily, 1)} дня при {daily} единицах в день. При переносе части заказов сразу вычтите подтверждённые резервы. Для большой партии важно оценить, как много денег уйдёт в товар и какую часть реально успеют продать.",
        f"Если {product} поступит на два дня позже, расход составит {daily * (lead + 2)}. Точка заказа станет {order_point + daily * 2}. При текущих {available} расчётный остаток перед приходом будет {available - daily * (lead + 2)}. В сценарии спроса на 20% больше в исходные {lead} дней расход приблизится к {ceil(daily * 1.2 * lead)}. Эти варианты лучше проверять раздельно, а при высокой неопределённости можно применить одновременно. Если рыночный спрос всплесками, набросайте таблицу по дням и выделите праздники и промо.",
        f"В собственном расчёте выберите доступный остаток для одного предложения. Товар в дороге, у сотрудника на осмотре или под обязательством относится к другой строке. Его можно включить на дату, когда появится подтверждённая возможность использовать. Для аналитики закупок селлера Яндекс Маркета следите за датой резерва, а для экономики доставленных единиц используйте соответствующее событие из отчёта. В примере короткий цикл позволяет использовать {daily} как повседневный темп без отдельной задержки между резервом и доставкой.",
        f"Подтвердите, из чего сложились {lead} дней. У разных поставщиков ход заказа может включать оплату, комплектацию, перевозку и внутреннюю приёмку. Если все эти интервалы уже включены, повторно прибавлять приёмку нельзя. Если {buffer} единиц резерва выбрали в прошлом сезоне, оцените, как часто остаток приближался к нулю. Для товаров с малыми партиями и быстрой заменой допустим иной резерв, чем для дорогого товара, который собирают по заказу. Число должно быть связано с конкретным риском и сроком.",
        f"Под конец периода сверьте два факта: когда заявка на {lot} была принята и когда товар стал доступен. Уточните, совпал ли расход {daily} в день с планом. Если продажи случались только в отдельные дни, добавьте отметки, чтобы при следующем решении не принять простой средний темп за закономерность. Разовый сбой удобнее описать одним сценарием задержки, а повторяющийся сдвиг учесть в основном сроке. При планировании следующей поставки укажите, какой запас уже обещан под другие каналы."
    )


MODELS = {"01": margin, "02": investment, "03": quality, "04": cash, "05": stock}


def mix(values, resource):
    stock, a_qty, b_qty, a_profit, b_profit = values
    def choose(total):
        best = max((b * b_profit + ((total - b * b_qty) // a_qty) * a_profit, b)
                   for b in range(total // b_qty + 1))
        b = best[1]
        a, remainder = divmod(total - b * b_qty, a_qty)
        return a, b, remainder, best[0]
    a, b, left, total = choose(stock)
    low = choose(stock * 4 // 5)
    high = choose(ceil(stock * 1.2))
    rows=[("Расход ресурса на продажу", a_qty, b_qty), ("Вклад за продажу", rub(a_profit), rub(b_profit)),
          ("Вклад на единицу ресурса", rub(a_profit / a_qty, 2), rub(b_profit / b_qty, 2)),
          ("Число продаж в расчётном сочетании", a, b)]
    return Model(
        f"Как использовать запас {stock} единиц",
        ("Показатель","Вариант А","Вариант Б"),rows,
        f"Ограничение в примере называется «{resource}». Доступно {stock} единиц. На продажу варианта А требуется {a_qty}, вклад {rub(a_profit)}. На вариант Б требуется {b_qty}, вклад {rub(b_profit)}. На одну единицу ограниченного ресурса выходит {rub(a_profit / a_qty, 2)} и {rub(b_profit / b_qty, 2)} соответственно. Это отношение стоит поставить рядом с вкладом на продажу. Оно показывает цену выбора, когда дополнительный комплект забирает то, из чего могли собрать другой.",
        f"Проверяем целые сочетания на запасе {stock}. Для каждого допустимого количества Б вычитаем использованный ресурс и делим остаток на {a_qty}, округляя вниз. Затем умножаем полученные количества на вклад каждого варианта и сравниваем суммы. Максимум при допущении достаточного спроса: А {a} продаж, Б {b}, остаётся {left} единиц ресурса, вклад {rub(total)}. Больший вклад на деталь помогает найти выгодный вариант, но из-за остатков отдельных деталей стоит проверить целые сочетания. Если спрос ограничен, добавьте верхний предел на продажи каждого варианта перед перебором.",
        f"При запасе {stock * 4 // 5} модель выбирает {low[0]} продаж варианта А и {low[1]} варианта Б с вкладом {rub(low[3])}. При запасе {ceil(stock * 1.2)} получится {high[0]} и {high[1]} продаж с вкладом {rub(high[3])}. Эти сценарии удобны, пока фактическое состояние материала ещё уточняют. Если значения резко сдвигаются, проверьте, в какой момент весь запас уже можно распределить без остатка. Для доступного места на складе или времени сборки можно добавить ещё один предел, если он действительно мешает выполнить расчётное сочетание.",
        f"Аналитика ассортимента селлера Яндекс Маркета помогает считать ресурсы на артикул. Для «{resource}» сначала укажите одинаковую единицу измерения. Детали из разных партий могут отличаться размером и быть взаимозаменяемыми только в части наборов. В учебном примере общая составляющая подходит обоим вариантам. Для черновика не нужно распределять все затраты магазина: возьмите чистую выручку и прямые расходы по одной продаже, а расходы периода добавьте после расчёта, если они изменятся между сценариями.",
        f"Сверьте входные {stock} единиц с фактическим доступным количеством. Склад может показать общий остаток до резервирования, а менеджер уже обещал часть наборов. Тогда в аналитику добавьте отдельный снимок до изменения и фактическое количество после резерва. Подтвердите расход на штуку по фактической сборке, особенно если сотрудник добавляет запасную деталь или меняет упаковку. Для товаров Яндекс Маркета полезно различать артикул готового набора и код компонента во внутренней системе.",
        f"К концу проверки сопоставьте выпуск с продажами. Из {a + b} собранных единиц не все успеют уйти, если модель переоценила спрос. Если часть готовых наборов останется, посчитайте время разборки, остаточную стоимость компонентов и дату следующего поставщика. В таблице храните два разных числа: вклад на доступную деталь при продаже и результат фактически доставленных наборов. После обновления цен замените {rub(a_profit)} и {rub(b_profit)} новыми прямыми итогами и пересчитайте выбранное сочетание."
    )


def report(values, item):
    initial, missing, duplicates, raw, added, removed = values
    corrected = raw + missing * added - duplicates * removed
    rows=[("Строки: исходник и проверенный итог", initial, initial+missing-duplicates),
          ("Сумма: исходник и проверенный итог", rub(raw), rub(corrected)),
          ("Подтверждено к добавлению", missing, rub(missing*added)),
          ("Подтверждено к исключению", duplicates, rub(duplicates*removed))]
    return Model(
        "Как изменились число строк и денежный итог",
        ("Показатель","Объём или исходник","Результат или сумма"),rows,
        f"В условной сводной {initial} строк на {rub(raw)}. Проверяем один вид записи, обозначенный «{item}». По исходникам пропущено {missing} записей, в примере по {rub(added)}. Их вклад в итог {rub(missing * added)}. Повторно внесли {duplicates} записей по {rub(removed)}, их сумма {rub(duplicates * removed)}. После исправления получаем {initial + missing - duplicates} строк и {rub(corrected)}. Арифметика независима от того, являются строки расходом или отдельным видом поступления. В своём учёте примените правильный знак к каждому типу движения.",
        f"От одной сверки суммы ошибки могут остаться незаметными. Чистая разница здесь {rub(corrected - raw)}, хотя суммарное движение исправлений {rub(missing * added + duplicates * removed)}. Представьте, что мы отразили только пропуски: было бы {rub(raw + missing * added)} и {initial + missing} строк. Только при снятии дублей вышло бы {rub(raw - duplicates * removed)} и {initial - duplicates} строк. Поэтому удобно отдельно вести строки добавления, исключения и замены. Если обнаружили замену оценки фактической величиной, сохраните доказательство обеих частей.",
        f"Допустим, статусы двух найденных добавлений ещё спорные. Учтём {max(0, missing - 2)} подтверждённых записей и сохраним остальные для проверки. Пока можно опираться на {rub(raw + max(0, missing - 2) * added - duplicates * removed)}. Если сомнение относится только к одному из дублей, первый результат будет {rub(corrected + removed)} при условии сохранения этого повтора до подтверждения. Механическое правило совпадения по сумме не подтверждает оба варианта. Зафиксируйте, какой итог идёт в рабочий прогноз и на какую дату нужно вернуться к исходникам.",
        f"В финансовой аналитике селлеров Яндекс Маркета у строки есть источник, время попадания в выгрузку и рабочий смысл. Полезно объяснить отдельно, чем является «{item}» для исходной системы. Если одинаковое событие нужно показать и в операционном отчёте, и в финансовом, это две точки зрения на запись. При объединении проверяйте идентификатор операции и принадлежность артикулу, магазину и периоду. Если это строки движения денег и услуг, сравнивайте сопоставимые события и оставьте способ вернуться к первичному документу.",
        f"Чтобы {initial} исходных строк было легко проверить, храните оригинальный экспорт отдельно от рабочей таблицы. Для ручного разбора обычно достаточно журнала: источник, идентификатор, исходная сумма, новая сумма и подтверждённая причина. Исходная выгрузка может обновляться, поэтому запишите дату её получения. Если спустя неделю пришёл более полный файл, первым шагом сверяйте фильтры. Существующие суммы не потеряются в случайно суженном периоде, если итог по магазину и типу события сохранён отдельно.",
        f"После проверки {initial + missing - duplicates} строк снова получите контрольный итог без ручных правок ячеек. Для теста повторите ту же выгрузку на предыдущей неделе и сравните группы, которые уже закрыли. Если сумма второй загрузки меняется, объясните разницу статусом или правилами замены. Проверьте, что ставить итог {rub(corrected)} можно в выбранный отчёт, и оставьте ссылку на записи, которые ещё требуют проверки. Так следующая аналитика по Яндекс Маркету не унаследует спорную сумму как факт."
    )


def route(values, name):
    boxes, trips, trip_cost, box_cost, fixed = values
    old = trips * trip_cost
    new = boxes * box_cost + fixed
    threshold = (old - fixed) // box_cost
    low = boxes * 3 // 4
    high = ceil(boxes * 1.25)
    rows=[("Переданных коробок",boxes,boxes),("Поездки, оплаченные по тарифу рейса",trips,"Включены в расчёт по коробке"),
          ("Постоянный расход сценария","0 ₽",rub(fixed)),("Итоговая стоимость за период",rub(old),rub(new)),
          ("Средняя стоимость коробки",rub(old / boxes, 2),rub(new / boxes, 2))]
    return Model(
        "Плата за рейсы и плата по коробкам",
        ("Показатель","Исходный маршрут","Альтернативный маршрут"),rows,
        f"Сценарий «{name}» сравниваем на {boxes} переданных коробках. В исходной схеме {trips} рейсов стоят по {rub(trip_cost)}. Всего {rub(old)}. В альтернативе прямая плата {rub(box_cost)} за коробку и {rub(fixed)} фиксированно за тот же период. Умножаем и складываем: {rub(new)}. Разница «альтернатива минус исходный» составляет {rub(new - old)}. За одну коробку в среднем выходит {rub(old / boxes, 2)} и {rub(new / boxes, 2)}. В итоговом расчёте убедитесь, что меняются именно те перевозки, за которые больше не придётся платить в исходной схеме.",
        f"Если прежние {trips} рейсов и их цена сохраняются при разных объёмах, то альтернативный вариант стоит не больше прежнего при объёме до {threshold} коробок. Вычитаем фикс {rub(fixed)} из {rub(old)}, затем делим результат на {rub(box_cost)} и округляем вниз. При {threshold + 1} коробках альтернативный вариант стоит {rub((threshold + 1) * box_cost + fixed)}. Когда число рейсов тоже меняется от объёма, сравнивайте не с постоянным порогом, а с реальным числом рейсов. В частности, дополнительная машина может поднять стоимость исходного маршрута посреди диапазона.",
        f"Сценарий на тихий период: {low} коробок при тех же {trips} рейсах. Альтернативный расход {rub(low * box_cost + fixed)}, исходный {rub(old)}. При {high} коробках на неизменном числе рейсов альтернативный расход {rub(high * box_cost + fixed)}. Если по плану перевозок при {high} нужен ещё рейс, исходный расход станет {rub(old + trip_cost)}. Запас вместимости проверяйте по объёму и весу коробок, поскольку число может показывать одинаковую загрузку только на действительно одинаковом потоке.",
        f"Селлеры Яндекс Маркета часто сравнивают отдельный счёт за транспорт с расходом на единицу. В первую очередь уравняйте состав услуги: откуда забирают, когда и в какое место привозят, какие коробки берут. Расход «{name}» удобно описать с границами передачи. Если варианты различаются по сроку, добавьте его в таблицу отдельно. Ускорение отгрузки может повлиять на количество исполненных заказов, но в текущем расчёте считаем только подтверждаемые затраты перевозки при том же объёме.",
        f"Разберите {trips} рейсов: подтверждённое время, фактическое количество коробок, дополнительные операции и счёт. Отказы в приёмке и повторные поездки отметьте отдельными событиями. Если в одном предложении перевозчика доплата за ожидание не включена, не считайте её нулевой до проверки. Аналитика доставки должна показать, какая часть сегодняшнего маршрута действительно отпадёт. Если готовы заменить лишь половину операций, сравните отдельно стоимость заменённого сегмента и стоимость той части, которая останется.",
        f"Сведите факт не сразу после отправки, а после оплаты подтверждённых услуг за выбранный период. Если реально передали {boxes} коробок, проверьте, сошёлся ли расчёт расхода на одну. Если часть оказалась другой категории по габаритам или условиям, вынесите её в другой сегмент. Даже при условно более дешёвом результате держите график и требования к передаче рядом с цифрами. Тогда при смене условий Яндекс Маркета или сторонней перевозки можно обновить конкретное допущение, а не пересобирать весь лист."
    )


def recovery(values, name):
    units, residual, cost, recovered, successful = values
    p = successful / 100
    delta = recovered - residual
    expect = residual + p * delta - cost
    target = cost / delta
    rows=[("Чистое поступление при успехе",rub(residual),rub(recovered)),
          ("Чистое поступление при неудачной попытке до затрат",rub(residual),rub(residual)),
          ("Затраты на одну попытку","0 ₽",rub(cost)),
          ("Ожидаемый итог на осмотренную единицу",rub(residual, 2),rub(expect, 2)),
          ("Ожидаемый итог для группы",rub(residual*units),rub(expect*units, 2))]
    return Model(
        "Остаточная стоимость и эффект восстановления",
        ("Показатель","Без обработки","С обработкой"),rows,
        f"Для группы из {units} единиц рассчитываем «{name}». Без обработки с одной пригодной к альтернативному использованию единицы остаётся {rub(residual)}. После успешной обработки чистое поступление оцениваем в {rub(recovered)}. Одна попытка стоит {rub(cost)} во всех случаях. Если доля удачных попыток {successful}%, а при неудачной попытке прежняя остаточная стоимость сохраняется, ожидаемый итог равен {rub(residual)} + {pct(p,0)} × {rub(delta)} − {rub(cost)} = {rub(expect,2)} на единицу. На группе получается {rub(expect * units,2)} против {rub(residual * units)} без обработки.",
        f"Порог задаёт отношение стоимости попытки {rub(cost)} к прибавке в случае успеха {rub(delta)}. При сохранении прежней остаточной стоимости за пределами удачных случаев нужно достичь примерно {pct(target,2)} подтверждённых успехов. Для {units} объектов это как минимум {ceil(target * units)} удачных результатов при тех же ставках. Если неудачная попытка делает товар непригодным даже для альтернативного использования, поменяйте остаток в сценарии неудачи и пересчитайте. В числителе нового порога появится потеря остаточной стоимости, а разница между успешным и неуспешным исходом тоже изменится.",
        f"Если доля успеха на 10 процентных пунктов ниже ожидания и составляет {max(0,successful-10)}%, на единицу ожидаем {rub(residual + max(0,p-.1) * delta - cost, 2)}. При улучшении до {min(100,successful+10)}% выходит {rub(residual + min(1,p+.1) * delta - cost, 2)}. При малом объёме держите рядом фактически осмотренные количества. Один случай на {units} единиц меняет наблюдаемую долю примерно на {pct(1/units,2)}. В обучающем расчёте нет предположения, что каждый товар обязательно получит покупателя сразу после подтверждения пригодности.",
        f"В аналитике возвратов на Яндекс Маркете удобно разделять причину возврата, заключение осмотра и следующий шаг. Для «{name}» выберите одну группу с одинаковым видом повреждения или недокомплекта. Перед решением подтвердите требования к допустимости продажи, точность описания и состояние товара по правилам категории. Восстановление может дать отдельный эффект, но пригодность должна подтверждаться после проверки. Непригодные единицы исключите из вариантов повторной продажи и рассмотрите другой правомерный путь обращения с ними.",
        f"Что включить в {rub(cost)} за попытку? Труд, использованные материалы, повторную проверку и прочие прямые расходы выбранной операции. Чистое поступление {rub(recovered)} считаем после тех затрат продажи или передачи, которые уже относятся к ней. Не вычитайте их ещё раз из стоимости работы. Если работа требует оборудования или тарифа на всю партию, выделите фикс отдельно и сравните его на объёме {units}. Потерянное время продажи полезно показывать датами осмотра и возвращения в доступ, особенно если товар залежался после сезона.",
        f"После пилота выпишите число попыток и подтверждённых успехов. Посмотрите, получилось ли приблизиться к {ceil(target*units)} пригодным результатам при сопоставимой группе. Отдельно подтвердите реальное чистое поступление после завершения продаж, если это уже видно. В расчёте возвратов удобны две даты: когда решили вернуть товар в оборот и когда подтвердили результат в деньгах. Если показатель по более новой партии отличается, сохраните старые значения как историю, а правило примените к новой группе после осмотра."
    )


def experiment(values, measurement):
    a_n, a_x, b_n, b_x, contribution=values
    a, b = a_x / a_n, b_x / b_n
    equivalent = b_n * a
    change = b_x - equivalent
    error = NormalDist().inv_cdf(0.975) * ((a*(1-a)/a_n) + (b*(1-b)/b_n))**.5
    rows=[("Измеренный объём",a_n,b_n),("Заказанные единицы",a_x,b_x),("Единиц на 100 наблюдений",fmt(a*100,2),fmt(b*100,2)),
          ("Заказы при исходном отношении и новом объёме","Сравнение по базовой группе",fmt(equivalent,1))]
    return Model(
        "Два периода на сравнимых основаниях",
        ("Показатель","До изменения","После изменения"),rows,
        f"В первой группе {a_n} наблюдений вида «{measurement}», заказано {a_x} единиц. Во второй {b_n} и {b_x}. На 100 наблюдений выходит {fmt(a*100,2)} и {fmt(b*100,2)}. Если бы вторая группа сохранила отношение первой, модель ожидала бы {fmt(equivalent,1)} заказанной единицы. Арифметическая разница с фактом {fmt(change,1)} единицы. Это сопоставление агрегатов. Показ или переход может относиться к тому же человеку несколько раз, а один заказ может содержать несколько единиц. Зафиксируйте, как считались шаги, прежде чем делать вывод о поведении покупателей.",
        f"Чтобы понять величину изменения, переведём разницу в одинаковый масштаб. На 1 000 событий исходное отношение дало бы около {fmt(a*1000,1)} заказанной единицы, наблюдаемое после правки {fmt(b*1000,1)}. Разница {fmt((b-a)*1000,1)}. При учебном вкладе {rub(contribution)} с доставленной единицы и допущении, что вся дополнительная величина дошла до доставки, денежный ориентир для текущего объёма {rub(change * contribution)}. Это сценарная оценка. Чтобы узнать фактический результат, используйте доставленные единицы одной зрелой группы, учитывайте изменение чистой цены, расходов и возвратов.",
        f"Повторите оценку на более осторожном варианте: допустим, до доставки доходит только 80% разницы. Тогда при {rub(contribution)} вклада условный ориентир {rub(change * .8 * contribution)}. Для простого случайного эксперимента с независимыми наблюдениями и максимум одной заказанной единицей на событие приближённая неопределённость разности составила бы около {fmt(error * 100,2)} процентного пункта с каждой стороны. У обычных недель магазина предпосылки могут быть другими. Для рабочего сравнения сохраните наблюдаемые количества и не переносите этот интервал на агрегаты с повторными показами или покупками нескольких единиц.",
        f"Начните с того, что определите «{measurement}» в источнике. Аналитика Яндекс Маркета может показывать разные показатели в зависимости от отчёта, а цена, срок доставки и доступность предложения могут меняться вместе с карточкой. Периоды сравниваются при одинаковых фильтрах. Если поменялась доля рекламы, используйте доступный разрез по источнику. Если до правки товар отсутствовал часть периода, сначала сравните окна наличия. Запишите момент изменения, чтобы первые дни со старой версией не попали в сравниваемую группу.",
        f"Проверьте, не изменилось ли число товаров в одном наблюдаемом заказе. {a_x} и {b_x} из примера относятся к заказанным единицам. У пользователя, который заказал сразу три, вклад в этот числитель другой, чем у покупателя одной штуки. Если для решения нужны реальные покупатели, используйте отчёт с подходящим показателем и разными определениями групп. Учтите повторные посещения. Промежуточный отчёт можно собрать быстро, но у завершённого финального периода одинаковый возраст и известный статус большинства заказов.",
        f"После теста сформулируйте, какой показатель будете проверять через следующую неделю. Например, сохраните отношение {fmt(b*100,2)} на 100 наблюдений и сравните его с группой, в которой цена и доступность сохранились. Если изменение наблюдается только в один день, проверьте размер того дня и события из журнала. Затем свяжите итог с фактическим вкладом и причинами обращений: если покупка стала понятнее, это может быть заметно по вопросам и возвратам, прежде чем вы увидите уверенную разницу в прибыли."
    )


MODELS.update({"06": mix, "07": report, "08": route, "09": recovery, "10": experiment})
